    name: { de: "Kirche der Heiligen Euphemia", hu: "Szent Eufémia-templom", ro: "Biserica Sfânta Eufemia", en: "Church of St. Euphemia"},
    image: "/poi-images/croatia-st-euphemia-church-landmarks-v2.webp",
